INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-what-is-java', 'core-java', 'Java Introduction', 'What is Java', 'Beginner', 10, 'Understand what Java is, James Gosling''s Green Project, the 3 major Java Editions (Java SE, Jakarta EE, Java ME), and the complete historical timeline from 1991 to modern Java 21 & 25.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-features-of-java', 'core-java', 'Java Introduction', 'Features of Java', 'Beginner', 12, 'Deep dive into the 14 core features of Java: Platform Independence (WORA), Object-Oriented, Simple, Secure, Robust, Multithreaded, High Performance (JIT), Distributed, Dynamic, Portable, Scalable, Versatile, Rich API, and Community.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-use-of-java', 'core-java', 'Java Introduction', 'Use of Java', 'Beginner', 10, 'Explore the major real-world usage domains of Java: Web Development, Enterprise Applications, Android Mobile Apps, Desktop GUIs, Scientific Research, Big Data, Embedded Systems, and Cloud Computing.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-softwares-download-installation', 'core-java', 'Java Introduction', 'Java Softwares Download & Installation', 'Beginner', 8, 'Essential software tools for learning Java: Java Development Kit (JDK), Text Editors (Notepad, Notepad++, TextEdit, Gedit), and modern IDEs (IntelliJ IDEA, Eclipse, NetBeans, VS Code), along with installation links and step-by-step video guides.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-jdk-jre-jvm', 'core-java', 'Java Introduction', 'JDK, JRE & JVM', 'Beginner', 15, 'Master the architectural relationship and core definitions: What is JDK (Development Tools + JRE), What is JRE (Java Package Classes + Runtime Libraries + JVM), and What is JVM (ClassLoader + Memory Areas + Execution Engine).');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-structure-of-program', 'core-java', 'Java Introduction', 'Structure of Java Program', 'Beginner', 15, 'Master the standardized structure of every Java program recommended by experts: Package Declarations (Optional), Import Statements (If necessary), Class Definition Statements, and Class Members (Variables, Constructors, Methods, and the main() method).');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-hello-program-deep-dive', 'core-java', 'Java Introduction', 'Java Hello Program Deep Explanation', 'Beginner', 15, 'Forensic 18-element line-by-line architectural breakdown of the simple Java Hello Program: access modifiers, static keyword, return types, command-line arguments, System.out.println, and syntax delimiters.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-compile-run-program', 'core-java', 'Java Introduction', 'Compile & Run Java Program', 'Beginner', 12, 'Step-by-step tutorial on compiling and running Java programs using Notepad and Windows Command Prompt (CMD), understanding javac, java commands, drive switching (/d), and .class bytecode generation.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-intro-how-java-works', 'core-java', 'Java Introduction', 'How Java Works', 'Beginner', 12, 'Deep step-by-step visual explanation of how Java works: writing source code, compilation with javac, bytecode (.class file), JVM execution, and screen output.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-terminologies-data-types', 'core-java', 'Programming Language Terminologies', 'Data Types', 'Beginner', 15, 'Comprehensive guide to Data Types in Java: Purpose, Memory Allocation, Primitive (8 types) vs Non-Primitive (Classes, Interfaces, Arrays, Collections, Enums), Dynamic Sizing, Garbage Collection, and 20-point Deep Comparison Matrix.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-terminologies-variables', 'core-java', 'Programming Language Terminologies', 'Variables', 'Beginner', 15, 'Understand Java Variables: Definition, real-world bus analogy, RAM memory allocation (4 bytes for int), 3 variable types (Local, Instance, Static), execution scope rules, and comprehensive comparison table.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-terminologies-literals', 'core-java', 'Programming Language Terminologies', 'Literals', 'Beginner', 15, 'Comprehensive guide to Java Literals: Integer (Decimal, Binary 0b, Octal 0, Hex 0x), Floating-Point (Float f, Double, Scientific Notation e), Character & Escape Sequences, String, Boolean, Null, and Java 7 Underscores in numbers.');
