INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-control-statements-star-patterns', 'core-java', 'Control Statements', 'Star Pattern Programs (18)', 'Beginner', 25, 'Master 18 classic Java Star Pattern programs: Right Triangle, Pyramid, Diamond, Butterfly, Sandglass, Hollow shapes, and Pascal Triangles.');
