INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-oops-introduction', 'core-java', 'OOP''s Concepts', 'OOP''s Introduction', 'Beginner', 15, 'Comprehensive introduction to Object Oriented Programming in Java: Programming Paradigms (Procedural, OOP, Functional, Declarative), What is OOPS, the 6 Main Pillars of OOP (Class, Object, Inheritance, Polymorphism, Abstraction, Encapsulation), and why Java is strongly OOP but not purely OOP.');
