INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-introduction', 'core-java', 'Strings', 'Introduction', 'Beginner', 20, 'Master the foundational evolution of text representation in Java: Character Literals (16-bit Unicode), Character Arrays (mutable continuous memory), and Strings (immutable objects), plus String vs StringBuffer vs StringBuilder.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-class', 'core-java', 'Strings', 'String class', 'Beginner', 25, 'Master the java.lang.String class: Syntax, class hierarchy, CharSequence interface, 15+ master methods (length, charAt, substring, intern, compareTo), immutability properties, and the 6 reasons why String is declared final.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-memory-scp', 'core-java', 'Strings', 'String Memory Management (SCP)', 'Intermediate', 25, 'Master String Constant Pool (SCP) memory management in Java: literal reuse, Heap allocation with new keyword, intern() method, garbage collection behavior, and performance optimization.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-immutable', 'core-java', 'Strings', 'Immutable Strings', 'Intermediate', 20, 'Deep architectural dive into String Immutability: Why Java Strings are immutable, internal implementation (final byte[] value), security benefits, thread safety, and HashMap hashCode caching.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-stringbuffer', 'core-java', 'Strings', 'StringBuffer class', 'Intermediate', 20, 'Master java.lang.StringBuffer: A peer class of String providing mutable, thread-safe character sequences. Explore capacity growth formula (old*2 + 2), synchronization, and methods: append(), insert(), delete(), reverse().');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-stringbuilder', 'core-java', 'Strings', 'StringBuilder class', 'Intermediate', 20, 'Master java.lang.StringBuilder: High-performance, mutable character sequence introduced in Java 5. Explore non-synchronized architecture, 2x-3x speedup over StringBuffer, methods, and automatic javac string concatenation compiler optimization.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-comparison', 'core-java', 'Strings', 'String vs StringBuffer vs StringBuilder', 'Intermediate', 20, 'The definitive 3-way architectural comparison of String vs StringBuffer vs StringBuilder: Mutability, Thread-Safety, Memory Layout, Execution Speed, and Architectural Decision Matrix.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-stringtokenizer', 'core-java', 'Strings', 'StringTokenizer class', 'Intermediate', 20, 'Master java.util.StringTokenizer: A legacy utility class to break a string into individual tokens based on delimiters. Explore constructors, hasMoreTokens(), nextToken(), countTokens(), and comparison with String.split().');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-strings-programs', 'core-java', 'Strings', 'String Programs', 'Intermediate', 30, 'Master 20 essential Java String programming problems: Reverse String, Palindrome, Anagrams, Frequency Count, First Non-Repeating Character, Duplicate Removal, Word Reversal, Pangram, and Permutations.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-io-byte-vs-character-streams', 'core-java', 'Java Input/Output', 'Java I/O: Byte Streams vs Character Streams', 'Intermediate', 20, 'Master Java Input/Output (I/O) Streams: InputStream/OutputStream (8-bit bytes) vs Reader/Writer (16-bit characters), BufferedReader, and modern Java NIO.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-io-streams-core', 'core-java', 'Java Input/Output', 'Java I/O: Byte Streams, Character Streams & Files', 'Intermediate', 15, 'Understand java.io stream architecture: InputStream vs OutputStream (Byte streams), Reader vs Writer (Character streams), Scanner vs BufferedReader, and modern java.nio.file.Files.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-serialization-core', 'core-java', 'Serialization', 'Java Serialization, transient Keyword & serialVersionUID', 'Intermediate', 20, 'Master Java Object Serialization and Deserialization: Serializable interface, ObjectOutputStream/ObjectInputStream, the transient keyword for sensitive fields, and serialVersionUID versioning.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-serialization-core', 'core-java', 'Serialization', 'Object Serialization, Deserialization & transient', 'Intermediate', 15, 'Convert live in-memory Java objects into portable byte streams using java.io.Serializable, ObjectOutputStream, serialVersionUID version control, and transient fields.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-multithreading-lifecycle', 'core-java', 'Multithreading', 'Multithreading: Thread Creation & Lifecycle States', 'Intermediate', 25, 'Master Java Multithreading: Extending Thread class vs implementing Runnable vs Callable, Thread lifecycle states (NEW, RUNNABLE, BLOCKED, WAITING, TIMED_WAITING, TERMINATED), sleep, join, and daemon threads.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-multithreading-virtual-threads', 'core-java', 'Multithreading', 'ExecutorService & Java 21 Virtual Threads (Project Loom)', 'Advanced', 20, 'Master Thread Pools with ExecutorService and explore Java 21 Virtual Threads (Project Loom): Running millions of concurrent lightweight tasks without OS thread exhaustion.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-multithreading-core', 'core-java', 'Multithreading', 'Multithreading: Lifecycle, Runnable & Executors', 'Advanced', 15, 'Master concurrency fundamentals: Thread lifecycle states (NEW, RUNNABLE, BLOCKED, WAITING, TIMED_WAITING, TERMINATED), extending Thread vs implementing Runnable, and ExecutorService thread pooling.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-synchronization-locks', 'core-java', 'Synchronization', 'Race Conditions & synchronized Keyword', 'Intermediate', 20, 'Master Thread Synchronization in Java: Race conditions, critical sections, intrinsic object monitors, synchronized methods vs blocks, and class-level static locking.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-synchronization-locks', 'core-java', 'Synchronization', 'Synchronization: Monitors, volatile & Locks', 'Advanced', 15, 'Prevent race conditions, thread interference, and memory visibility issues using synchronized methods/blocks, JVM intrinsic object monitors, volatile variables, ReentrantLock, and deadlock prevention.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-collections-overview', 'core-java', 'Collections Framework', 'Java Collections Framework Architecture & Hierarchy', 'Beginner', 20, 'Master the Java Collections Framework architecture: Iterable, Collection, List, Set, Queue, Deque, and Map hierarchies, with core time complexities.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-collections-hashmap-internals', 'core-java', 'Collections Framework', 'HashMap Internals, Bucket Collisions & Treeification', 'Advanced', 25, 'Master HashMap Internal Working in Java 8+: Node<K,V> array buckets, hash(key) calculation, index formula (n-1 & hash), collision handling, load factor 0.75, and LinkedList to Red-Black Tree treeification at threshold 8.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-collections-framework-core', 'core-java', 'Collections Framework', 'Java Collections Framework: List, Set & Map', 'Intermediate', 15, 'Master the Java Collections Framework hierarchy: List (ArrayList, LinkedList), Set (HashSet, TreeSet), Map (HashMap, TreeMap, ConcurrentHashMap), Queue/Deque, and internal hashing algorithms.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-8-lambdas-functional-interfaces', 'core-java', 'Java 8 Features', 'Lambda Expressions & Functional Interfaces', 'Beginner', 20, 'Master Java 8 Lambda Expressions and Built-in Functional Interfaces: @FunctionalInterface, Predicate, Function, Consumer, Supplier, and Method References.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-8-streams-api-pipeline', 'core-java', 'Java 8 Features', 'Stream API: Pipelines, Intermediate & Terminal Operations', 'Intermediate', 25, 'Master the Java 8 Stream API: Lazy evaluation, filter, map, flatMap, distinct, sorted, reduce, collect (groupingBy, partitioningBy), and parallel streams.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-8-features-core', 'core-java', 'Java 8 Features', 'Java 8 Features: Lambdas, Streams & Optionals', 'Intermediate', 15, 'Master modern functional programming in Java: Lambda expressions, Functional Interfaces (@FunctionalInterface, Predicate, Consumer, Function, Supplier), Stream API (filter, map, reduce), and Optional handling.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-generics-type-erasure', 'core-java', 'Other Topics', 'Java Generics & Type Erasure', 'Intermediate', 20, 'Master Java Generics: Compile-time type safety, eliminating ClassCastExceptions, Bounded Type Parameters (<T extends Number>), Wildcards (? extends T vs ? super T - PECS), and Type Erasure.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-other-topics-core', 'core-java', 'Other Topics', 'Generics, Enums, Annotations & Java 21 Records', 'Intermediate', 15, 'Explore essential advanced Java features: Generics & Type Erasure (<T>, wildcards <? extends T>), Enums with methods, Custom Annotations (@Retention, @Target), and Java 17/21 Records & Pattern Matching.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('java-core-interview-questions-top50', 'core-java', 'Interview Questions', 'Top 50 Core Java Interview Questions & Answers', 'Advanced', 35, 'Master the Top 50 most frequently asked Core Java interview questions across FAANG and Tier-1 tech firms: OOPs, JVM Memory, String Pool, Multithreading, Collections HashMap internals, Exception Handling, and Java 8 Streams.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('dsa-two-pointers-sliding-window', 'dsa', 'Arrays & Two Pointers', 'Two Pointers & Sliding Window Patterns: O(N) Invariants', 'Medium', 15, 'Master Opposite-Direction Two Pointers (Two Sum II, Container With Most Water, Trapping Rain Water) and Variable/Fixed-Size Sliding Windows (Longest Substring Without Repeating Characters, Minimum Window Substring).');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('dsa-linked-list-algorithms', 'dsa', 'Linked Lists', 'Linked List Mastery: In-Place Reversal, Fast & Slow Pointers (Floyd Cycle)', 'Medium', 15, 'Master Linked List pointer manipulation: In-Place Reversal, Fast/Slow Pointers (Cycle Detection, Find Middle, Palindrome List), and Merge K Sorted Lists.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('spring-core-ioc-di', 'spring-boot', 'Spring Core & IoC', 'Spring Inversion of Control (IoC) & Dependency Injection (DI)', 'Intermediate', 14, 'Master the Spring ApplicationContext container, Bean Lifecycle hooks, Bean scopes (Singleton, Prototype, Request, Session), Constructor vs Field Injection, and Component Scanning.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('spring-web-dispatcherservlet', 'spring-boot', 'Web & Request Flow', 'Spring Web MVC: Deep Request Flow & DispatcherServlet Architecture', 'Intermediate', 16, 'Deep architectural trace of an HTTP request: Client -> Tomcat NIO -> Filter Chain -> DispatcherServlet -> HandlerMapping -> HandlerAdapter -> Controller -> HttpMessageConverter (Jackson JSON) -> Client.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-welcome-course-introduction', 'system-design', 'LLD - Welcome', 'Course Introduction', 'Beginner', 5, 'Welcome to an interactive and hands-on course designed to help you master Low-Level Design (LLD) from scratch and prepare for top-tier software engineering interviews.');
