INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-lld-introduction-lld-vs-hld', 'system-design', 'LLD - LLD Introduction', 'LLD vs HLD', 'Intermediate', 15, 'In software engineering, building a complex system is like constructing a city.');
