INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-uml-class-diagram', 'system-design', 'LLD - UML', 'Class Diagram', 'Intermediate', 15, 'Unified Modeling Language (UML) is a standard way to visualize the design of a software system.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-uml-use-case-diagram', 'system-design', 'LLD - UML', 'Use Case Diagram', 'Intermediate', 15, 'Imagine you’ve been asked to design a new software system—say, an online food delivery app. Before you dive into writing classes, functions, or database schemas, the first question is:');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-uml-sequence-diagram', 'system-design', 'LLD - UML', 'Sequence Diagram', 'Intermediate', 15, 'Imagine you''re ordering a pizza. You call the pizza place. The cashier takes your order, sends it to the kitchen, and the chef starts preparing it. Once it’s ready, a delivery person picks it up and brings it to your door.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-uml-activity-diagram', 'system-design', 'LLD - UML', 'Activity Diagram', 'Intermediate', 15, 'Describing complex workflows verbally is like giving someone driving directions with fifteen turns, three conditional detours, and two shortcuts. They''ll lose track by turn four.');
