INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-null-object-pattern', 'system-design', 'LLD - Design Patterns', 'Null Object Pattern', 'Intermediate', 15, 'Imagine you''re building a logging system. Different parts of your application need to log events, but some deployments need logging disabled entirely. You start sprinkling null checks everywhere:');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-repository-pattern', 'system-design', 'LLD - Design Patterns', 'Repository Pattern', 'Intermediate', 15, 'Imagine you’re building an order management system. Your service layer fetches orders, saves new ones, and runs queries like “orders placed today.” At first, you write SQL directly inside service classes. It works.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-mvc-pattern', 'system-design', 'LLD - Design Patterns', 'MVC Pattern', 'Intermediate', 15, 'Imagine you''re building an issue tracking system like Jira. You start with a single class that handles everything: fetching tasks from the database, formatting them as HTML, and processing form submissions.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-dependency-injection-pattern', 'system-design', 'LLD - Design Patterns', 'Dependency Injection Pattern', 'Intermediate', 15, 'Most codebases start clean, then slowly get messy in the same place: object creation inside business classes.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-specification-pattern-lld', 'system-design', 'LLD - Design Patterns', 'Specification Pattern | LLD', 'Intermediate', 15, 'Detailed notes and design patterns for Specification Pattern | LLD.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-game-loop-pattern', 'system-design', 'LLD - Design Patterns', 'Game Loop Pattern', 'Intermediate', 15, 'Imagine you’re building a simple game. Your character moves across the screen, enemies spawn, and the score updates. So you write code that waits for user input and then updates the game.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-thread-pool-pattern', 'system-design', 'LLD - Design Patterns', 'Thread Pool Pattern', 'Intermediate', 15, 'Imagine you are running a web server. It creates a new thread to handle each request. The thread processes the request, sends the response, and terminates. Simple enough.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-producer-consumer-pattern', 'system-design', 'LLD - Design Patterns', 'Producer-Consumer Pattern', 'Intermediate', 15, 'Imagine you''re building an application that processes user uploads. Users upload files, and your system needs to process them (resize images, scan for viruses, extract metadata).');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-design-patterns-quiz-additional-patterns-lld', 'system-design', 'LLD - Design Patterns', 'Quiz: Additional Patterns | LLD', 'Intermediate', 15, 'Detailed notes and design patterns for Quiz: Additional Patterns | LLD.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-lld-interview-tips-how-to-approach-ood-interviews-lld', 'system-design', 'LLD - LLD Interview Tips', 'How to approach OOD Interviews | LLD', 'Intermediate', 15, 'Detailed notes and design patterns for How to approach OOD Interviews | LLD.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-lld-interview-tips-how-to-approach-maching-coding-interviews-lld', 'system-design', 'LLD - LLD Interview Tips', 'How to approach Maching Coding Interviews | LLD', 'Intermediate', 15, 'Detailed notes and design patterns for How to approach Maching Coding Interviews | LLD.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-lld-interview-tips-how-to-identify-entities-and-model-relationships-in-lld-interviews', 'system-design', 'LLD - LLD Interview Tips', 'How to Identify Entities and Model Relationships in LLD Interviews', 'Intermediate', 15, 'In most LLD interviews, the quality of your solution depends heavily on how well you model the problem before writing any code. And at the heart of good modeling lies one critical skill: identifying the right entities and defining how they relate ...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-lld-interview-tips-how-to-write-clean-code-in-lld-interviews', 'system-design', 'LLD - LLD Interview Tips', 'How to Write Clean Code in LLD Interviews', 'Intermediate', 15, 'In LLD interviews, writing code that works is only half the battle. What truly sets strong candidates apart is their ability to write clean, structured, and maintainable code that reflects real-world engineering practices.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-lld-interview-tips-choosing-the-right-design-patterns', 'system-design', 'LLD - LLD Interview Tips', 'Choosing the Right Design Patterns', 'Advanced', 15, 'In LLD interviews, knowing design patterns is less important than knowing when to use them and why. In most interviews, you are evaluated on your design judgement and not on how many patterns you know.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-lld-interview-tips-how-to-handle-concurrency-in-lld-interviews', 'system-design', 'LLD - LLD Interview Tips', 'How to Handle Concurrency in LLD Interviews', 'Intermediate', 15, 'For mid-level roles and above, interviewers are not just checking whether you know OOP. They also want to see if you can design software that holds up in the messy reality of production systems. That’s where concurrency often becomes a differentia...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('lld-games-puzzles-design-tic-tac-toe-game', 'system-design', 'LLD - Games Puzzles', 'Design Tic Tac Toe Game', 'Advanced', 15, 'In this chapter, we will explore the low-level design of a tic tac toe game in detail.');
