INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-welcome-course-introduction', 'system-design', 'HLD - Welcome', 'Course Introduction', 'Intermediate', 15, 'Welcome to a course on System Design Fundamentals. I''m delighted to have you here.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-welcome-course-roadmap-system-design', 'system-design', 'HLD - Welcome', 'Course Roadmap | System Design', 'Advanced', 15, 'Detailed notes and design patterns for Course Roadmap | System Design.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-introduction-to-system-design-what-is-system-design', 'system-design', 'HLD - Introduction to System Design', 'What is System Design?', 'Advanced', 15, 'System design is the process of deciding how a software system should be structured so it can meet its requirements at the expected scale.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-introduction-to-system-design-30-must-know-system-design-concepts', 'system-design', 'HLD - Introduction to System Design', '30 Must-Know System Design Concepts', 'Advanced', 15, '[![YouTube Video](https://img.youtube.com/vi/s9Qh9fWeOAk/0.jpg)](https://www.youtube.com/watch\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-core-concepts-scalability', 'system-design', 'HLD - Core Concepts', 'Scalability', 'Intermediate', 15, 'As an application grows, the load on it grows too: more users, more data, more requests per second. A design that worked for a thousand users may not work for a million, and a database that served a hundred queries per second may not serve ten tho...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-core-concepts-availability', 'system-design', 'HLD - Core Concepts', 'Availability', 'Intermediate', 15, 'A system can be perfectly designed to handle millions of requests and still be useless to its users if it goes down whenever a single server fails. Scaling to high load and staying operational under failure are two different problems, and the seco...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-core-concepts-reliability', 'system-design', 'HLD - Core Concepts', 'Reliability', 'Intermediate', 15, 'A system that stays up but occasionally produces wrong answers is not actually serving its users. Beyond capacity and uptime, there is a third concern: reliability.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-core-concepts-single-point-of-failure', 'system-design', 'HLD - Core Concepts', 'Single Point of Failure', 'Intermediate', 15, 'A single point of failure (SPOF) is any component, dependency, process, or decision point whose failure can take down the system or a critical user flow.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-core-concepts-latency-vs-throughput-vs-bandwidth', 'system-design', 'HLD - Core Concepts', 'Latency vs Throughput vs Bandwidth', 'Intermediate', 15, 'When discussing system performance, three terms come up repeatedly: latency, throughput, and bandwidth. These concepts are often confused or used interchangeably, but they measure fundamentally different things.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-core-concepts-consistent-hashing', 'system-design', 'HLD - Core Concepts', 'Consistent Hashing', 'Intermediate', 15, 'Distributed systems often need a stable way to decide which node owns a key.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-core-concepts-cap-theorem', 'system-design', 'HLD - Core Concepts', 'CAP Theorem', 'Intermediate', 15, 'The CAP theorem is one of the most quoted ideas in distributed systems, and also one of the easiest to misuse.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-core-concepts-consistency-models', 'system-design', 'HLD - Core Concepts', 'Consistency Models', 'Intermediate', 15, 'Distributed systems keep copies of data in more than one place: primary databases, read replicas, caches, search indexes, vector indexes, event streams, analytics stores, and regional failover clusters.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-networking-osi-model', 'system-design', 'HLD - Networking', 'OSI Model', 'Intermediate', 15, 'The OSI (Open Systems Interconnection) model is a reference framework that divides network communication into seven layers, from raw bits on a wire to application-level protocols. ISO published it in the 1980s to give the industry a common vocabul...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-networking-ip-addresses', 'system-design', 'HLD - Networking', 'IP Addresses', 'Intermediate', 15, 'An IP address is the logical address Layer 3 uses to decide where packets should go. Routers, firewalls, load balancers, cloud networks, DNS, and service endpoints all depend on it.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-networking-tcp-vs-udp', 'system-design', 'HLD - Networking', 'TCP vs UDP', 'Intermediate', 15, 'TCP and UDP are the two transport protocols that sit directly above IP. Both solve the same problem of delivering data between processes using ports, but they make very different tradeoffs.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-networking-httphttps', 'system-design', 'HLD - Networking', 'HTTP/HTTPS', 'Intermediate', 15, 'HTTP (Hypertext Transfer Protocol) is the application protocol behind the web, most public APIs, and a large share of internal service-to-service traffic. HTTPS is the same protocol carried over TLS (Transport Layer Security), which is the default...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-networking-domain-name-system-dns', 'system-design', 'HLD - Networking', 'Domain Name System (DNS)', 'Intermediate', 15, 'DNS (Domain Name System) is the distributed, hierarchical naming system that turns names such as api.example.com into the records clients need to connect to a service. It is also one of the first control planes engineers reach for to point a domai...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-networking-checksums', 'system-design', 'HLD - Networking', 'Checksums', 'Intermediate', 15, 'A checksum is a compact value computed from data so a system can later check whether that data has changed. The producer computes the value, stores or transmits it alongside the data, and the consumer recomputes and compares.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-networking-proxy-vs-reverse-proxy', 'system-design', 'HLD - Networking', 'Proxy vs Reverse Proxy', 'Intermediate', 15, 'A proxy is an intermediary that forwards network traffic on behalf of another party. The useful distinction is which party it represents: a forward proxy represents the client, and a reverse proxy represents the server.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-load-balancing-load-balancers', 'system-design', 'HLD - Load Balancing', 'Load Balancers', 'Intermediate', 15, 'A load balancer sits between clients and backend services. It accepts traffic on a stable address, picks a healthy backend, and forwards the request.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-load-balancing-load-balancing-algorithms', 'system-design', 'HLD - Load Balancing', 'Load Balancing Algorithms', 'Intermediate', 15, 'A load balancing algorithm is the policy a load balancer uses to pick the next backend. The right policy depends on the workload. A static web server, a WebSocket service, a cache cluster, and an AI inference gateway each need a different one.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-load-balancing-dns-load-balancing', 'system-design', 'HLD - Load Balancing', 'DNS Load Balancing', 'Intermediate', 15, 'DNS load balancing steers clients by returning different DNS answers for the same hostname. The authoritative DNS service can pick an address based on health, weight, geography, latency, or failover state.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-load-balancing-anycast-routing', 'system-design', 'HLD - Load Balancing', 'Anycast Routing', 'Intermediate', 15, 'Anycast routing lets multiple locations advertise the same IP prefix. The internet routes each client toward one reachable instance based on BGP path selection, not a central decision maker.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-whats-an-api', 'system-design', 'HLD - API Fundamentals', 'What''s an API?', 'Intermediate', 15, 'API stands for Application Programming Interface. An API is a contract that lets one piece of software use another without knowing its internal implementation. The contract defines what operations are available, what inputs are accepted, what outp...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-idempotency', 'system-design', 'HLD - API Fundamentals', 'Idempotency', 'Intermediate', 15, 'Idempotency is the property that running an operation multiple times has the same intended effect as running it once. It is what lets a client safely retry a request after a network failure, a timeout, or an ambiguous response.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-data-formats', 'system-design', 'HLD - API Fundamentals', 'Data Formats', 'Intermediate', 15, 'Every time two systems communicate, they need to agree on a common language. When a mobile app fetches user data from a server, when microservices exchange messages through Kafka, or when you store configuration in a file, data formats are working...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-api-architectural-styles', 'system-design', 'HLD - API Fundamentals', 'API Architectural Styles', 'Intermediate', 15, 'An API architectural style is the set of conventions an API follows for how clients express intent, how servers expose capability, how failures are reported, how contracts evolve, and how traffic behaves under load. REST, GraphQL, gRPC, WebSocket,...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-rest-api-design-best-practices', 'system-design', 'HLD - API Fundamentals', 'REST API Design Best Practices', 'Advanced', 15, 'REST remains the default API style for public web APIs, product backends, partner integrations, and many internal services. It works because HTTP is everywhere, tooling is mature, JSON is easy to inspect, and the model is simple enough for clients...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-graphql-deep-dive', 'system-design', 'HLD - API Fundamentals', 'GraphQL Deep Dive', 'Intermediate', 15, 'If you''ve built APIs using REST, you''ve probably run into its limitations. A mobile app needs just a user''s name and avatar, but the /users/123 endpoint returns 30 fields. Or worse, you need data from three different endpoints to render a single s...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-grpc-deep-dive', 'system-design', 'HLD - API Fundamentals', 'gRPC Deep Dive', 'Intermediate', 15, 'gRPC is a contract-first RPC framework built around Protocol Buffers and HTTP/2. A .proto file defines the service. Code generation produces typed clients and server interfaces in every supported language. Calls carry deadlines, cancellation, meta...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-api-gateways', 'system-design', 'HLD - API Fundamentals', 'API Gateways', 'Intermediate', 15, 'An API gateway is the controlled entry point for client traffic. Browsers, mobile apps, partner integrations, and AI agents call the gateway instead of each backend service directly. The gateway applies edge policy, chooses the right backend route...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-rate-limiting', 'system-design', 'HLD - API Fundamentals', 'Rate Limiting', 'Intermediate', 15, 'Rate limiting controls how much work a client is allowed to send into a system over a time window. It is an admission-control decision: for each incoming request, the system decides whether to let it start, reject it, or delay it.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-authentication-authorization', 'system-design', 'HLD - API Fundamentals', 'Authentication & Authorization', 'Intermediate', 15, 'Authentication and authorization are separate security decisions.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-session-based-vs-token-based-authentication', 'system-design', 'HLD - API Fundamentals', 'Session-Based vs Token-Based Authentication', 'Intermediate', 15, 'After a user signs in, every later request needs a way to prove it belongs to the same authenticated user.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-jwt', 'system-design', 'HLD - API Fundamentals', 'JWT', 'Intermediate', 15, 'A JSON Web Token (JWT) is a compact, URL-safe token format used to carry claims between systems.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-oauth-20', 'system-design', 'HLD - API Fundamentals', 'OAuth 2.0', 'Intermediate', 15, 'OAuth 2.0 is a protocol for delegated authorization.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-api-fundamentals-single-sign-on-sso', 'system-design', 'HLD - API Fundamentals', 'Single Sign-On (SSO)', 'Intermediate', 15, 'Single Sign-On (SSO) lets users authenticate with one trusted identity system and then access multiple applications without each application handling passwords directly.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-long-polling-explained', 'system-design', 'HLD - Communication Patterns', 'Long Polling Explained', 'Intermediate', 15, 'Suppose you are building notifications and want users to see new messages soon after they arrive, but a WebSocket connection feels like more machinery than the product needs.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-websockets', 'system-design', 'HLD - Communication Patterns', 'WebSockets', 'Intermediate', 15, 'HTTP is a request-response protocol: the client asks, the server responds, and the application moves on. That model is awkward when the server needs to push data the moment something happens, such as a new chat message, a price tick, or a collabor...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-server-sent-events', 'system-design', 'HLD - Communication Patterns', 'Server-Sent Events', 'Intermediate', 15, 'Suppose you are building a live dashboard. The server needs to push updates whenever a job finishes, a metric changes, or a new alert appears, but the browser does not need to send messages back over the same connection.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-webhooks', 'system-design', 'HLD - Communication Patterns', 'Webhooks', 'Intermediate', 15, 'Suppose you run an e-commerce system and use a payment provider such as [Stripe](https://stripe.com/). When a payment succeeds, your system needs to mark the order paid, send a receipt, and notify fulfillment. The catch is that you do not control ...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-webrtc', 'system-design', 'HLD - Communication Patterns', 'WebRTC', 'Intermediate', 15, 'Most real-time web features keep a server in the middle. Long polling, SSE, and WebSockets are good fits for notifications, chat, dashboards, and collaborative state, all of which route data through your application servers.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-synchronous-vs-asynchronous-communication', 'system-design', 'HLD - Communication Patterns', 'Synchronous vs Asynchronous Communication', 'Intermediate', 15, 'When a user clicks Place Order, several things have to happen: validating the cart, checking prices, creating the order, reserving inventory, capturing payment, sending a confirmation email, and updating analytics.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-message-queues', 'system-design', 'HLD - Communication Patterns', 'Message Queues', 'Intermediate', 15, 'A message queue lets one part of a system send work to another part without waiting for that work to finish immediately.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-publish-subscribe-pubsub', 'system-design', 'HLD - Communication Patterns', 'Publish-Subscribe (Pub/Sub)', 'Intermediate', 15, 'When an order is placed, several independent systems may need to react. Inventory may reserve stock, notifications may send a confirmation email, analytics may record the event, fraud detection may evaluate the order, and shipping may prepare fulf...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-change-data-capture-cdc', 'system-design', 'HLD - Communication Patterns', 'Change Data Capture (CDC)', 'Intermediate', 15, 'Most production databases do not live alone. The same data may need to appear in a search index, cache, data warehouse, fraud system, recommendation pipeline, or another service.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-delivery-semantics', 'system-design', 'HLD - Communication Patterns', 'Delivery Semantics', 'Intermediate', 15, 'When a system sends a message, several things can go wrong.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-communication-patterns-dead-letter-queues', 'system-design', 'HLD - Communication Patterns', 'Dead Letter Queues', 'Intermediate', 15, 'Retries are useful only when a failure might go away. A network timeout, a busy database, or a temporary service outage is worth retrying.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-what-is-caching', 'system-design', 'HLD - Caching', 'What is Caching?', 'Intermediate', 15, 'A cache is a fast storage layer that holds copies of frequently used data so requests can be served without hitting slower systems like databases or external APIs.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-cache-aside-pattern', 'system-design', 'HLD - Caching', 'Cache-Aside Pattern', 'Intermediate', 15, 'The first design question in caching is simple:');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-read-through-vs-write-through-cache', 'system-design', 'HLD - Caching', 'Read-Through vs Write-Through Cache', 'Intermediate', 15, 'In the cache-aside pattern, the application owns the caching logic.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-write-behind-cache', 'system-design', 'HLD - Caching', 'Write-Behind Cache', 'Intermediate', 15, 'Write-through caching waits for the database before acknowledging a write. That keeps the write path simple, but every write pays database latency.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-caching-strategies-summary', 'system-design', 'HLD - Caching', 'Caching Strategies Summary', 'Intermediate', 15, 'A caching strategy defines how an application reads from and writes to the cache. Each strategy trades off latency, consistency, complexity, and failure behavior differently.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-cache-eviction-policies', 'system-design', 'HLD - Caching', 'Cache Eviction Policies', 'Intermediate', 15, 'A cache is useful because it keeps hot data close to the application.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-content-delivery-network-cdn', 'system-design', 'HLD - Caching', 'Content Delivery Network (CDN)', 'Intermediate', 15, 'A Content Delivery Network (CDN) is a distributed layer of edge servers that sits between users and your origin servers.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-distributed-cache-architecture', 'system-design', 'HLD - Caching', 'Distributed Cache Architecture', 'Advanced', 15, 'A cache keeps frequently used data in fast storage, usually memory, so the application does not have to recompute it or fetch it from a slower database on every request.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-cache-invalidation-system-design', 'system-design', 'HLD - Caching', 'Cache Invalidation | System Design', 'Advanced', 15, 'Detailed notes and design patterns for Cache Invalidation | System Design.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-cache-stampede', 'system-design', 'HLD - Caching', 'Cache Stampede', 'Intermediate', 15, 'A cache protects a database by absorbing repeated reads.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-caching-cache-warming', 'system-design', 'HLD - Caching', 'Cache Warming', 'Intermediate', 15, 'Caching works well when the data your users need is already close to the application.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-database-types', 'system-design', 'HLD - Databases', 'Database Types', 'Intermediate', 15, 'Choosing a database is one of the earliest system design decisions that has long-term consequences.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-sql-vs-nosql', 'system-design', 'HLD - Databases', 'SQL vs NoSQL', 'Intermediate', 15, '\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-acid-transactions', 'system-design', 'HLD - Databases', 'ACID Transactions', 'Intermediate', 15, 'A transaction is a group of database operations treated as one unit.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-relational-databases', 'system-design', 'HLD - Databases', 'Relational Databases', 'Intermediate', 15, 'Relational databases are still the default storage choice for many production systems.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-document-databases', 'system-design', 'HLD - Databases', 'Document Databases', 'Intermediate', 15, 'Document databases store records as JSON-like documents instead of rows spread across many tables.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-key-value-stores', 'system-design', 'HLD - Databases', 'Key-Value Stores', 'Intermediate', 15, 'A key-value store is the simplest database model: store a value under a key, then fetch it later using that same key.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-wide-column-databases', 'system-design', 'HLD - Databases', 'Wide-Column Databases', 'Intermediate', 15, 'Wide-column databases are built for large, distributed datasets where the access patterns are known in advance.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-graph-databases', 'system-design', 'HLD - Databases', 'Graph Databases', 'Intermediate', 15, 'Graph databases store data as entities and relationships.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-time-series-databases', 'system-design', 'HLD - Databases', 'Time-Series Databases', 'Intermediate', 15, 'Time-series data is data measured over time.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-full-text-search-engines', 'system-design', 'HLD - Databases', 'Full-Text Search Engines', 'Intermediate', 15, 'Full-text search engines are built for finding and ranking text.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-vector-databases', 'system-design', 'HLD - Databases', 'Vector Databases', 'Intermediate', 15, 'Vector databases store and search embeddings.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-b-trees-and-b-trees', 'system-design', 'HLD - Databases', 'B-Trees and B+ Trees', 'Intermediate', 15, 'When you run a query like this:');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-lsm-trees-log-structured-merge-trees', 'system-design', 'HLD - Databases', 'LSM Trees (Log-Structured Merge Trees)', 'Intermediate', 15, 'B+ trees are a strong default for read-heavy and mixed OLTP workloads. They keep index entries ordered in page-sized structures, which gives predictable point lookups and efficient range scans.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-databases-how-databases-guarantee-durability', 'system-design', 'HLD - Databases', 'How Databases Guarantee Durability', 'Intermediate', 15, 'Durability means that once a database reports a transaction as committed, the system should be able to recover that transaction after a failure.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-indexing', 'system-design', 'HLD - Database Scaling Techniques', 'Indexing', 'Intermediate', 15, 'A database index is a data structure that helps the database find rows without scanning the whole table.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-vertical-partitioning', 'system-design', 'HLD - Database Scaling Techniques', 'Vertical Partitioning', 'Intermediate', 15, 'Some tables become slow not because they have too many rows, but because each row is too wide.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-query-optimization', 'system-design', 'HLD - Database Scaling Techniques', 'Query Optimization', 'Intermediate', 15, 'Many database scaling problems start as query problems.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-read-replicas', 'system-design', 'HLD - Database Scaling Techniques', 'Read Replicas', 'Intermediate', 15, 'Most production applications read more than they write.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-denormalization', 'system-design', 'HLD - Database Scaling Techniques', 'Denormalization', 'Intermediate', 15, 'Normalized databases are excellent for correctness. Each fact lives in one place, updates are clean, and constraints are easier to enforce.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-materialized-views', 'system-design', 'HLD - Database Scaling Techniques', 'Materialized Views', 'Intermediate', 15, 'Many slow database queries do the same expensive work again and again.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-connection-pooling', 'system-design', 'HLD - Database Scaling Techniques', 'Connection Pooling', 'Intermediate', 15, 'Database connections are expensive resources.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-sharding', 'system-design', 'HLD - Database Scaling Techniques', 'Sharding', 'Intermediate', 15, 'Eventually, some databases outgrow a single machine.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-sharding-vs-partitioning', 'system-design', 'HLD - Database Scaling Techniques', 'Sharding vs Partitioning', 'Intermediate', 15, 'Sharding and partitioning are easy to confuse because both split data into smaller pieces.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-database-scaling-techniques-data-compression', 'system-design', 'HLD - Database Scaling Techniques', 'Data Compression', 'Intermediate', 15, 'Data compression reduces the number of bytes needed to store or transmit data. Fewer bytes can mean lower storage cost, less network traffic, faster disk reads, better cache density, and cheaper backups.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-storage-systems-block-vs-file-vs-object-storage', 'system-design', 'HLD - Storage Systems', 'Block vs File vs Object Storage', 'Intermediate', 15, 'Storage systems are not interchangeable buckets for bytes. The storage type you choose decides how applications read, write, share, protect, and pay for data.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-storage-systems-object-storage', 'system-design', 'HLD - Storage Systems', 'Object Storage', 'Intermediate', 15, 'Object storage is the storage model behind services like Amazon S3, Google Cloud Storage, Azure Blob Storage, and MinIO. It is built for large amounts of unstructured data: images, videos, backups, logs, exports, ML datasets, and data lake files.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-storage-systems-distributed-file-systems', 'system-design', 'HLD - Storage Systems', 'Distributed File Systems', 'Advanced', 15, 'A local file system manages files on one machine. A distributed file system (DFS) manages files across many machines while presenting a shared namespace to clients.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-storage-systems-erasure-coding', 'system-design', 'HLD - Storage Systems', 'Erasure Coding', 'Intermediate', 15, 'Replication is the simplest way to protect data: store multiple copies. If one copy is lost, read another one.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-tradeoffs-vertical-vs-horizontal-scaling', 'system-design', 'HLD - Tradeoffs', 'Vertical vs Horizontal Scaling', 'Intermediate', 15, 'Scaling starts with a bottleneck: CPU, memory, disk I/O, network bandwidth, database locks, GPU memory, or some shared dependency that has become saturated. Once the bottleneck is identified, there are two ways to add capacity.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-tradeoffs-concurrency-vs-parallelism', 'system-design', 'HLD - Tradeoffs', 'Concurrency vs Parallelism', 'Intermediate', 15, 'Concurrency and parallelism are related ideas that solve different problems.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-tradeoffs-push-vs-pull-architecture', 'system-design', 'HLD - Tradeoffs', 'Push vs Pull Architecture', 'Intermediate', 15, 'Push and pull describe who initiates data movement.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-tradeoffs-stateful-vs-stateless-architecture', 'system-design', 'HLD - Tradeoffs', 'Stateful vs Stateless Architecture', 'Intermediate', 15, 'Every useful system has state somewhere: accounts, orders, carts, files, conversations, model outputs, workflow progress, locks, and database rows. The architectural question is where that state lives.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-tradeoffs-long-polling-vs-websockets', 'system-design', 'HLD - Tradeoffs', 'Long Polling vs WebSockets', 'Intermediate', 15, 'Many products need to deliver updates without forcing the user to refresh: chat messages, build statuses, payment changes, cursor movements in a shared document, AI tokens streaming back from a model.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-tradeoffs-strong-vs-eventual-consistency', 'system-design', 'HLD - Tradeoffs', 'Strong vs Eventual Consistency', 'Intermediate', 15, 'Distributed systems usually keep more than one copy of important data. When one copy changes, the consistency model decides what other clients are allowed to see.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-challenges-of-distribution', 'system-design', 'HLD - Distributed System Fundamentals', 'Challenges of Distribution', 'Intermediate', 15, 'A distributed system is one whose work is spread across multiple machines that communicate over a network.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-network-partitions', 'system-design', 'HLD - Distributed System Fundamentals', 'Network Partitions', 'Intermediate', 15, 'A network partition happens when parts of a distributed system can no longer communicate with each other.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-split-brain-problem', 'system-design', 'HLD - Distributed System Fundamentals', 'Split Brain Problem', 'Intermediate', 15, 'Split-brain is a failure mode where more than one node believes it is the leader and starts making authoritative decisions.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-heartbeats', 'system-design', 'HLD - Distributed System Fundamentals', 'Heartbeats', 'Intermediate', 15, 'A heartbeat is a small periodic message that says, \\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-handling-failures-in-distributed-systems', 'system-design', 'HLD - Distributed System Fundamentals', 'Handling Failures in Distributed Systems', 'Advanced', 15, 'Distributed systems fail in pieces.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-clock-synchronization-problem', 'system-design', 'HLD - Distributed System Fundamentals', 'Clock Synchronization Problem', 'Intermediate', 15, 'Time feels absolute on one machine. In a distributed system, it is not. Every machine has its own clock, those clocks drift apart, and synchronizing them happens over a network with variable delay.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-logical-clocks', 'system-design', 'HLD - Distributed System Fundamentals', 'Logical Clocks', 'Intermediate', 15, 'Physical clocks answer \\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-lamport-timestamps', 'system-design', 'HLD - Distributed System Fundamentals', 'Lamport Timestamps', 'Intermediate', 15, 'Lamport timestamps are the simplest useful logical clock. Each process keeps one integer counter, and that counter moves forward on local events, sends, and receives.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-vector-clocks', 'system-design', 'HLD - Distributed System Fundamentals', 'Vector Clocks', 'Intermediate', 15, 'Lamport timestamps preserve causal order in one direction: if A -> B, then L(A) < L(B). The reverse does not hold. A smaller Lamport timestamp could mean A caused B, or it could mean A and B were concurrent. Vector clocks add enough information to...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-consensus-algorithms-overview', 'system-design', 'HLD - Distributed System Fundamentals', 'Consensus Algorithms Overview', 'Intermediate', 15, 'Consensus is how a group of machines agrees on one decision even when some machines fail and messages are delayed.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-paxos-algorithm', 'system-design', 'HLD - Distributed System Fundamentals', 'Paxos Algorithm', 'Intermediate', 15, 'Paxos is the classic consensus algorithm for crash-fault-tolerant distributed systems.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-raft-algorithm', 'system-design', 'HLD - Distributed System Fundamentals', 'Raft Algorithm', 'Intermediate', 15, 'Raft is a consensus algorithm for building a replicated log.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-leader-election', 'system-design', 'HLD - Distributed System Fundamentals', 'Leader Election', 'Intermediate', 15, 'Leader election is the process of choosing one node to coordinate work for a group.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-distributed-locks', 'system-design', 'HLD - Distributed System Fundamentals', 'Distributed Locks', 'Advanced', 15, 'A distributed lock gives one client exclusive access to a shared resource across many processes and machines.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-gossip-protocol', 'system-design', 'HLD - Distributed System Fundamentals', 'Gossip Protocol', 'Intermediate', 15, 'A gossip protocol spreads information through a cluster by having nodes periodically exchange state with a small number of peers.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-crdts', 'system-design', 'HLD - Distributed System Fundamentals', 'CRDTs', 'Intermediate', 15, 'A Conflict-Free Replicated Data Type is a data structure designed to be replicated across many nodes, updated independently, and merged into the same final state without coordination.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-system-fundamentals-operational-transformation', 'system-design', 'HLD - Distributed System Fundamentals', 'Operational Transformation', 'Intermediate', 15, 'Operational Transformation (OT) lets multiple users edit the same document at the same time and end up with the same final state, with no locks and no waiting between users.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-transactions-the-problem-with-distributed-transactions', 'system-design', 'HLD - Distributed Transactions', 'The Problem with Distributed Transactions', 'Advanced', 15, 'A local transaction is simple because one database owns the data. The application runs a sequence of statements, and the database commits everything or rolls everything back.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-transactions-two-phase-commit-2pc', 'system-design', 'HLD - Distributed Transactions', 'Two-Phase Commit (2PC)', 'Intermediate', 15, 'Two-Phase Commit (2PC) is the classic protocol for atomic commit across multiple transactional resources. It answers one narrow question: can several participants agree to commit or abort the same transaction\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-transactions-three-phase-commit-3pc', 'system-design', 'HLD - Distributed Transactions', 'Three-Phase Commit (3PC)', 'Intermediate', 15, 'Three-Phase Commit (3PC) is an atomic commit protocol designed to reduce the blocking problem in Two-Phase Commit.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-transactions-saga-pattern', 'system-design', 'HLD - Distributed Transactions', 'Saga Pattern', 'Intermediate', 15, 'The Saga pattern coordinates a long-running business workflow as a sequence of local transactions across multiple services.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-distributed-transactions-outbox-pattern', 'system-design', 'HLD - Distributed Transactions', 'Outbox Pattern', 'Intermediate', 15, 'The Outbox pattern lets a service update its database and publish an event without a distributed transaction across the two.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-data-structures-for-scale', 'system-design', 'HLD - Data Structures for Scale', 'Data Structures for Scale', 'Intermediate', 15, 'A web crawler tracks billions of URLs. A ride-sharing app finds nearby drivers across a global fleet. A replicated database holds terabytes per node. A hash set, B-tree, or sorted array does not handle workloads like these.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-geohash', 'system-design', 'HLD - Data Structures for Scale', 'Geohash', 'Intermediate', 15, 'Many location systems need to find nearby places without scanning every latitude and longitude row.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-quad-trees', 'system-design', 'HLD - Data Structures for Scale', 'Quad Trees', 'Intermediate', 15, 'Many systems need to find nearby objects in two-dimensional space without checking every point.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-r-trees', 'system-design', 'HLD - Data Structures for Scale', 'R-Trees', 'Intermediate', 15, 'Many spatial systems need to query objects by shape, such as points, rectangles, lines, and polygons.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-s2-and-h3', 'system-design', 'HLD - Data Structures for Scale', 'S2 and H3', 'Intermediate', 15, 'Global systems often need to group, query, and aggregate locations across the entire Earth.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-bloom-filters', 'system-design', 'HLD - Data Structures for Scale', 'Bloom Filters', 'Intermediate', 15, 'A Bloom filter answers one narrow question:');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-cuckoo-filter', 'system-design', 'HLD - Data Structures for Scale', 'Cuckoo Filter', 'Intermediate', 15, 'Some systems need approximate membership checks, but also need deletion.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-hyperloglog', 'system-design', 'HLD - Data Structures for Scale', 'HyperLogLog', 'Intermediate', 15, 'Analytics systems often need distinct counts across shards, time buckets, tenants, and experiments.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-count-min-sketch', 'system-design', 'HLD - Data Structures for Scale', 'Count-Min Sketch', 'Intermediate', 15, 'Streaming systems often need frequency estimates for large, unbounded, or distributed event streams.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-minhash', 'system-design', 'HLD - Data Structures for Scale', 'MinHash', 'Intermediate', 15, 'Many systems need to compare sets without comparing every element.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-skip-lists', 'system-design', 'HLD - Data Structures for Scale', 'Skip Lists', 'Intermediate', 15, 'Many systems need an ordered in-memory structure for lookups, updates, range scans, and iteration.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-data-structures-for-scale-merkle-trees-explained', 'system-design', 'HLD - Data Structures for Scale', 'Merkle Trees Explained', 'Intermediate', 15, 'When you download a large file from the internet, how do you know it hasn''t been corrupted or tampered with\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-client-server-architecture', 'system-design', 'HLD - Architectural Patterns', 'Client-Server Architecture', 'Intermediate', 15, 'Client-server architecture separates request initiators from shared services that process work and protect resources.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-monolithic-architecture', 'system-design', 'HLD - Architectural Patterns', 'Monolithic Architecture', 'Intermediate', 15, 'Monolithic architecture packages an application as one deployable unit, even when its code is split into internal modules.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-microservices-architecture', 'system-design', 'HLD - Architectural Patterns', 'Microservices Architecture', 'Intermediate', 15, 'Microservices architecture structures a system as independently deployable services organized around business capabilities.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-serverless-architecture', 'system-design', 'HLD - Architectural Patterns', 'Serverless Architecture', 'Intermediate', 15, 'Serverless architecture runs application code on provider-managed compute and backend services.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-event-driven-architecture', 'system-design', 'HLD - Architectural Patterns', 'Event-Driven Architecture', 'Intermediate', 15, 'Event-driven architecture lets systems publish facts about business changes and lets interested consumers react asynchronously.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-peer-to-peer-p2p-architecture', 'system-design', 'HLD - Architectural Patterns', 'Peer to Peer (P2P) Architecture', 'Intermediate', 15, 'Most of the internet runs on a client-server model. You (the client) request a webpage from a central server (like Google''s), and the server sends it back to you.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-hexagonal-architecture', 'system-design', 'HLD - Architectural Patterns', 'Hexagonal Architecture', 'Intermediate', 15, 'Hexagonal architecture organizes an application so business logic stays at the center and external systems connect through explicit ports and adapters.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-cqrs', 'system-design', 'HLD - Architectural Patterns', 'CQRS', 'Intermediate', 15, 'CQRS separates commands that change state from queries that read state.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-architectural-patterns-event-sourcing', 'system-design', 'HLD - Architectural Patterns', 'Event Sourcing', 'Intermediate', 15, 'Event sourcing stores state changes as an append-only sequence of events instead of storing only the latest state.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-microservices-patterns-service-discovery', 'system-design', 'HLD - Microservices Patterns', 'Service Discovery', 'Intermediate', 15, 'In a monolith, components call each other inside one process. In a distributed system, that call becomes a network request to an instance whose address can change at any time.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-microservices-patterns-api-gateway-pattern', 'system-design', 'HLD - Microservices Patterns', 'API Gateway Pattern', 'Intermediate', 15, 'Service discovery helps services find each other inside the system. External clients still need a stable and controlled way to enter it.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-microservices-patterns-backend-for-frontend-bff', 'system-design', 'HLD - Microservices Patterns', 'Backend for Frontend (BFF)', 'Intermediate', 15, 'An API gateway gives clients a controlled entry point. A Backend for Frontend goes one step further: it gives each client experience an API shaped for that experience.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-microservices-patterns-sidecar-pattern', 'system-design', 'HLD - Microservices Patterns', 'Sidecar Pattern', 'Intermediate', 15, 'Distributed systems repeat the same operational work across many services: log shipping, metrics collection, TLS, tracing, configuration sync, and traffic policy.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-microservices-patterns-circuit-breaker-pattern', 'system-design', 'HLD - Microservices Patterns', 'Circuit Breaker Pattern', 'Intermediate', 15, 'Remote calls fail in ways local function calls do not. A dependency can return errors, time out, throttle requests, or become so slow that callers run out of threads and connection pools while waiting.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-microservices-patterns-bulkhead-pattern', 'system-design', 'HLD - Microservices Patterns', 'Bulkhead Pattern', 'Intermediate', 15, 'A distributed system often fails through shared resources before it fails through code.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-microservices-patterns-strangler-fig-pattern', 'system-design', 'HLD - Microservices Patterns', 'Strangler Fig Pattern', 'Intermediate', 15, 'Modernization usually happens while the old system is still serving users.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-microservices-patterns-service-mesh', 'system-design', 'HLD - Microservices Patterns', 'Service Mesh', 'Intermediate', 15, 'Service-to-service communication becomes hard to govern once a system has many independently deployed services.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-deployment-strategies-overview', 'system-design', 'HLD - Deployment Patterns', 'Deployment Strategies Overview', 'Intermediate', 15, 'A deployment strategy is the plan for moving a new version of an application from a build artifact to live production traffic without breaking the system in front of real users.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-cicd-pipelines', 'system-design', 'HLD - Deployment Patterns', 'CI/CD Pipelines', 'Intermediate', 15, 'A CI/CD pipeline is the automated path that a code change travels from a developer''s commit to a running version of the application in production.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-rolling-deployments', 'system-design', 'HLD - Deployment Patterns', 'Rolling Deployments', 'Intermediate', 15, 'A rolling deployment replaces the running version of an application incrementally. The system swaps out instances a batch at a time: new instances come up on the new version, old instances drain and shut down, and some part of the fleet keeps serv...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-blue-green-deployments', 'system-design', 'HLD - Deployment Patterns', 'Blue-Green Deployments', 'Intermediate', 15, 'A blue-green deployment runs two complete copies of the production environment side by side. Blue serves live traffic. Green runs the new version. When green is ready, the system flips traffic from blue to green in one step, with blue staying onli...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-canary-releases', 'system-design', 'HLD - Deployment Patterns', 'Canary Releases', 'Intermediate', 15, 'A canary release sends a small slice of production traffic to a new version, watches what happens, and only continues if the metrics look good. Named after the canaries miners carried to detect dangerous gases: a small subject goes in first, and t...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-feature-flags', 'system-design', 'HLD - Deployment Patterns', 'Feature Flags', 'Intermediate', 15, 'A feature flag is a conditional in the code that decides at runtime whether a particular behavior is on or off. The deployment ships the code; the flag turns the feature on.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-ab-testing-infrastructure', 'system-design', 'HLD - Deployment Patterns', 'A/B Testing Infrastructure', 'Intermediate', 15, 'An A/B test randomly assigns users to two or more variants of a product experience, measures how each variant performs on a chosen metric, and uses the difference to decide which version to ship. The infrastructure that powers it is what lets a co...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-zero-downtime-schema-migrations', 'system-design', 'HLD - Deployment Patterns', 'Zero-Downtime Schema Migrations', 'Intermediate', 15, 'A schema migration is any change to the structure of a database: adding a column, renaming, dropping a table, changing a type, adding an index. On a small project, it is one command and a restart. On a production system with live users, the same c...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-deployment-patterns-rollbacks-and-immutable-infrastructure', 'system-design', 'HLD - Deployment Patterns', 'Rollbacks and Immutable Infrastructure', 'Intermediate', 15, 'A rollback moves a system from a broken state back to a known good state. Immutable infrastructure is the practice of building infrastructure once and never modifying it in place, so that \\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-observability-three-pillars-of-observability', 'system-design', 'HLD - Observability', 'Three Pillars of Observability', 'Intermediate', 15, 'Observability is the ability to understand what is happening inside a system by examining its outputs. It helps teams answer why a system is behaving a certain way, not only whether it is up.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-observability-logging-best-practices', 'system-design', 'HLD - Observability', 'Logging Best Practices', 'Intermediate', 15, 'Logging records meaningful events from a running system so engineers can understand what happened during normal operation, failures, and investigations.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-observability-alerting-monitoring', 'system-design', 'HLD - Observability', 'Alerting & Monitoring', 'Intermediate', 15, 'Alerting turns important observability signals into timely notifications when a system needs human attention.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-observability-dashboards-runbooks', 'system-design', 'HLD - Observability', 'Dashboards & Runbooks', 'Intermediate', 15, 'Dashboards organize observability data for decision-making, and runbooks turn operational knowledge into repeatable response steps.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-observability-distributed-tracing', 'system-design', 'HLD - Observability', 'Distributed Tracing', 'Advanced', 15, 'Distributed tracing records the path of a request or workflow through instrumented parts of a system.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-welcome-course-roadmap-system-design-interview-algomasterio', 'system-design', 'HLD Interviews - Welcome', 'Course Roadmap | System Design Interview | AlgoMaster.io', 'Advanced', 15, 'Detailed notes and design patterns for Course Roadmap | System Design Interview | AlgoMaster.io.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-welcome-course-introduction', 'system-design', 'HLD Interviews - Welcome', 'Course Introduction', 'Core', 5, 'Welcome to System Design Interviews Masterclass. Master real-world scalability, trade-offs, architecture patterns, and 55+ FAANG interview problems.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-introduction-introduction-to-system-design-interviews', 'system-design', 'HLD Interviews - Introduction', 'Introduction to System Design Interviews', 'Advanced', 15, 'A system design interview is an open-ended conversation where you are asked to design a real-world system in 45 to 60 minutes.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-introduction-types-of-system-design-questions', 'system-design', 'HLD Interviews - Introduction', 'Types of System Design Questions', 'Advanced', 15, 'Not every system design question should be answered the same way.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-introduction-expectations-by-experience-level', 'system-design', 'HLD Interviews - Introduction', 'Expectations by Experience Level', 'Intermediate', 15, 'A system design interview is not graded on one universal scale.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-must-know-topics-must-know-concepts-for-system-design-interviews', 'system-design', 'HLD Interviews - Must Know Topics', 'Must-Know Concepts for System Design Interviews', 'Advanced', 15, 'System design interviews test your knowledge of how large-scale systems work. Without a solid foundation in core concepts, you''ll struggle to design systems or explain your decisions.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-must-know-topics-must-know-technologies-for-system-design-interviews', 'system-design', 'HLD Interviews - Must Know Topics', 'Must-Know Technologies for System Design Interviews', 'Advanced', 15, 'Understanding system design concepts is essential. But you also need to know the technologies that implement those concepts.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-must-know-topics-must-know-tradeoffs-for-system-design-interviews', 'system-design', 'HLD Interviews - Must Know Topics', 'Must-Know Tradeoffs for System Design Interviews', 'Advanced', 15, 'Every system design decision is a tradeoff.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-must-know-topics-must-know-data-structures-for-system-design-interviews', 'system-design', 'HLD Interviews - Must Know Topics', 'Must-Know Data Structures for System Design Interviews', 'Advanced', 15, 'The data structures that matter in system design are different from what you learned in your algorithms course.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-concept-deep-dives-networking-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Concept Deep Dives', 'Networking Deep Dive for System Design Interviews', 'Advanced', 15, 'Every system design interview involves networking. Whether you are designing a chat application, URL shortener, or video streaming platform, data must travel between clients and servers across networks.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-concept-deep-dives-caching-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Concept Deep Dives', 'Caching Deep Dive for System Design Interviews', 'Advanced', 15, 'Caching appears in virtually every system design interview. Whether you are designing a social media feed, e-commerce platform, or URL shortener, caching is essential for achieving low latency and high throughput.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-concept-deep-dives-api-design-for-system-design-interviews', 'system-design', 'HLD Interviews - Concept Deep Dives', 'API Design for System Design Interviews', 'Advanced', 15, 'In almost every system design interview, you’re expected to define the APIs for the system you’re designing.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-concept-deep-dives-database-design-for-system-design-interviews', 'system-design', 'HLD Interviews - Concept Deep Dives', 'Database Design for System Design Interviews', 'Advanced', 15, 'In every system design interview, you''ll face the question: \\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-concept-deep-dives-distributed-systems-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Concept Deep Dives', 'Distributed Systems Deep Dive for System Design Interviews', 'Advanced', 15, 'Distributed systems are at the heart of every modern tech company. When your interviewer asks \\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-postgresql-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'PostgreSQL Deep Dive for System Design Interviews', 'Advanced', 15, 'In system design interviews, PostgreSQL often shows up as the default answer for “the main database.” And for good reason: it’s a battle-tested relational database with strong consistency, rich querying, and reliable transactions.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-mysql-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'MySQL Deep Dive for System Design Interviews', 'Advanced', 15, 'MySQL is one of the most widely deployed databases in the world, which means you’ll run into it everywhere: early-stage startups, massive enterprise systems, and plenty of system design interviews.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-mongodb-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'MongoDB Deep Dive for System Design Interviews', 'Advanced', 15, 'MongoDB shows up in system design discussions for one simple reason: it makes it easy to scale and ship fast. When your data is naturally document-shaped (profiles, carts, activity feeds, content metadata), MongoDB can feel like the “default choice.”');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-redis-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Redis Deep Dive for System Design Interviews', 'Advanced', 15, 'When an interviewer asks you to design a rate limiter, leaderboard, or session store, one technology comes up almost every time: Redis.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-memcached-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Memcached Deep Dive for System Design Interviews', 'Advanced', 15, 'Memcached is the original distributed caching system and remains one of the most efficient solutions for high-throughput caching workloads. Companies like Facebook, Twitter, and YouTube rely on Memcached to handle billions of requests per day with...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-dynamodb-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'DynamoDB Deep Dive for System Design Interviews', 'Advanced', 15, 'When Amazon needed a database that could handle Prime Day, they built DynamoDB. In 2023, DynamoDB processed over 89 million requests per second during peak traffic, powering the shopping carts, inventory checks, and order processing that make the ...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-cassandra-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Cassandra Deep Dive for System Design Interviews', 'Advanced', 15, 'Cassandra shows up when the system design problem has a very specific shape: massive write volume, huge data size, multi-region availability, and a tolerance for eventual consistency.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-elasticsearch-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Elasticsearch Deep Dive for System Design Interviews', 'Advanced', 15, 'When a system design problem involves search, Elasticsearch is often the first technology that comes up. From powering e-commerce product search to aggregating billions of log events, Elasticsearch has become the default choice for search-heavy ap...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-kafka-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Kafka Deep Dive for System Design Interviews', 'Advanced', 15, 'Imagine you''re designing a system that needs to handle millions of events per second. Orders flow in from an e-commerce platform, clicks stream from a website, and logs pour in from hundreds of microservices. You need to capture all of this data r...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-rabbitmq-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'RabbitMQ Deep Dive for System Design Interviews', 'Advanced', 15, 'Picture this: you''re building an e-commerce system where placing an order needs to trigger half a dozen downstream actions. Inventory must be reserved, a confirmation email sent, analytics updated, fraud detection run, and a shipping label generat...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-amazon-sqs-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Amazon SQS Deep Dive for System Design Interviews', 'Advanced', 15, 'Imagine you''re designing an image processing system. Users upload photos, and your service needs to generate thumbnails, extract metadata, run content moderation, and update search indexes. If you process these synchronously in the upload request,...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-flink-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Flink Deep Dive for System Design Interviews', 'Advanced', 15, 'Imagine you are building a fraud detection system that needs to analyze millions of credit card transactions per second, correlate them with user behavior patterns, and flag suspicious activity before the transaction completes.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-spark-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Spark Deep Dive for System Design Interviews', 'Advanced', 15, 'Imagine you are building an analytics platform for an e-commerce company. Every day, you need to process 50 million user events, join them with product catalogs and user profiles, compute aggregated metrics, train recommendation models, and popula...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-amazon-s3-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Amazon S3 Deep Dive for System Design Interviews', 'Advanced', 15, 'Walk into any system design interview involving file storage, and S3 will almost certainly come up.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-aws-lambda-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'AWS Lambda Deep Dive for System Design Interviews', 'Advanced', 15, 'AWS Lambda is the most widely used serverless compute service. When you need to run code without managing servers, handle variable workloads, or build event-driven architectures, Lambda is often the go-to solution.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-nginx-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Nginx Deep Dive for System Design Interviews', 'Advanced', 15, 'Draw any system design diagram with multiple backend servers, and you''ll need something in front of them.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-zookeeper-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Zookeeper Deep Dive for System Design Interviews', 'Advanced', 15, 'If you have spent any time working with distributed systems, you have probably run into Zookeeper. It powers coordination in Kafka, HBase, Solr, and countless internal systems at large companies. Yet in interviews, I often see candidates either tr...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-docker-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Docker Deep Dive for System Design Interviews', 'Advanced', 15, 'Picture this: your application works perfectly on your laptop. Tests pass, features work, everything is smooth. Then you deploy to production, and it breaks. Different OS version, missing library, conflicting dependency. Hours of debugging later, ...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-kubernetes-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Kubernetes Deep Dive for System Design Interviews', 'Advanced', 15, 'Imagine you have 50 microservices, each running multiple instances across a cluster of machines. Some services need to scale up during peak hours. Others need to restart when they crash. You need to deploy new versions without downtime, route traf...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-technology-deep-dives-prometheus-deep-dive-for-system-design-interviews', 'system-design', 'HLD Interviews - Technology Deep Dives', 'Prometheus Deep Dive for System Design Interviews', 'Advanced', 15, 'Prometheus is the monitoring system you reach for when you want clear visibility into a distributed system, not just dashboards, but an explainable model for how metrics are collected, stored, queried, and alerted on.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-real-time-updates-in-system-design', 'system-design', 'HLD Interviews - Interview Patterns', 'Real-time Updates in System Design', 'Advanced', 15, 'Modern applications need to show users the latest information instantly. When a friend sends you a message, you expect to see it immediately. When a stock price changes, traders need to know within milliseconds. When someone likes your post, the n...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-fanout-pattern-in-system-design', 'system-design', 'HLD Interviews - Interview Patterns', 'Fanout Pattern in System Design', 'Advanced', 15, 'Fanout (sometimes called fan-out on write or fan-out on read) is the pattern you reach for when one event needs to reach many recipients—fast, reliably, and at scale.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-handling-high-read-traffic', 'system-design', 'HLD Interviews - Interview Patterns', 'Handling High Read Traffic', 'Intermediate', 15, 'Most real-world applications are read-heavy. For every user who posts a tweet, thousands read it. For every product listing created, millions view it. For every article published, countless readers access it. The read-to-write ratio in production ...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-handling-high-write-traffic', 'system-design', 'HLD Interviews - Interview Patterns', 'Handling High Write Traffic', 'Intermediate', 15, 'While most systems are read-heavy, some of the most challenging problems in distributed systems involve handling massive write loads. Every GPS ping from an Uber driver, every click tracked by analytics, every log line from a server, every IoT sen...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-handling-hot-keys', 'system-design', 'HLD Interviews - Interview Patterns', 'Handling Hot Keys', 'Intermediate', 15, 'What happens when Cristiano Ronaldo posts to his 650+ million Instagram followers\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-handling-traffic-spikes', 'system-design', 'HLD Interviews - Interview Patterns', 'Handling Traffic Spikes', 'Intermediate', 15, 'Your e-commerce platform handles 1,000 requests per second on a normal day. Then Black Friday hits, and suddenly you''re getting 50,000 requests per second. Servers crash, the database melts down, and thousands of customers see error pages instead ...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-handling-large-files', 'system-design', 'HLD Interviews - Interview Patterns', 'Handling Large Files', 'Intermediate', 15, 'A user tries to upload a 2 GB video file. After 45 minutes at 80% progress, their connection drops. They have to start over from scratch.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-real-time-media-streaming', 'system-design', 'HLD Interviews - Interview Patterns', 'Real-Time Media Streaming', 'Intermediate', 15, 'Media streaming is one of the most demanding challenges in distributed systems. It combines massive data volumes (video is heavy), strict timing requirements (frames must arrive on schedule), and highly variable client conditions (networks change ...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-handling-location-data-system-design-interview-algomasterio', 'system-design', 'HLD Interviews - Interview Patterns', 'Handling Location Data | System Design Interview | AlgoMaster.io', 'Advanced', 15, 'Detailed notes and design patterns for Handling Location Data | System Design Interview | AlgoMaster.io.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-generating-unique-ids', 'system-design', 'HLD Interviews - Interview Patterns', 'Generating Unique IDs', 'Intermediate', 15, 'You''re designing a URL shortener. Each shortened URL needs a unique identifier. Simple enough, you think. Just use an auto-incrementing database ID.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-distributed-counting-a-pattern-for-counting-at-scale', 'system-design', 'HLD Interviews - Interview Patterns', 'Distributed Counting: A Pattern for Counting at Scale', 'Advanced', 15, 'Counting sounds simple. Increment a number when something happens. How hard can it be\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-leader-election', 'system-design', 'HLD Interviews - Interview Patterns', 'Leader Election', 'Intermediate', 15, 'Imagine you have five database replicas. All of them can handle reads, but only one should handle writes. The question is: which one\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-failure-detection-and-heartbeats', 'system-design', 'HLD Interviews - Interview Patterns', 'Failure Detection and Heartbeats', 'Intermediate', 15, 'In distributed systems, nodes fail all the time. Servers crash, networks partition, processes hang. The question isn''t if failures happen, but how quickly you can detect them.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-handling-failures-in-distributed-systems', 'system-design', 'HLD Interviews - Interview Patterns', 'Handling Failures in Distributed Systems', 'Advanced', 15, 'Your payment service just crashed during Black Friday peak traffic. Thousands of orders are stuck mid-transaction. The recommendation engine is timing out, making the entire product page load slowly. Users are abandoning their carts. Revenue is bl...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-recommendations-pattern', 'system-design', 'HLD Interviews - Interview Patterns', 'Recommendations Pattern', 'Intermediate', 15, 'How does TikTok know exactly what videos will keep you scrolling for hours\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-multi-tenancy-pattern', 'system-design', 'HLD Interviews - Interview Patterns', 'Multi-Tenancy Pattern', 'Intermediate', 15, 'How does Slack keep a company''s messages separate from millions of other companies using the same platform\\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-multi-region-architecture', 'system-design', 'HLD Interviews - Interview Patterns', 'Multi-Region Architecture', 'Intermediate', 15, 'Your service is running smoothly in a single data center. Then an earthquake hits, the power grid fails, or a fiber cable gets cut. Suddenly, millions of users cannot access your application.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-deduplicating-data-in-system-design', 'system-design', 'HLD Interviews - Interview Patterns', 'Deduplicating Data in System Design', 'Advanced', 15, 'A user uploads the same 50MB video five times because their network kept dropping. Your storage costs just quintupled for a single file.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-distributed-transactions', 'system-design', 'HLD Interviews - Interview Patterns', 'Distributed Transactions', 'Advanced', 15, 'Picture this scenario: a customer clicks \\');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-interview-patterns-removing-single-points-of-failure', 'system-design', 'HLD Interviews - Interview Patterns', 'Removing Single Points of Failure', 'Intermediate', 15, 'Your system has been running fine for months. Then one server fails. A single server. Suddenly your entire application is down, thousands of users are affected, and your on-call engineer is scrambling at 3 AM.');
