INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-basic-questions-design-url-shortener-system-design-interview-algomasterio', 'system-design', 'HLD Interviews - Basic Questions', 'Design URL Shortener | System Design Interview | AlgoMaster.io', 'Advanced', 15, 'Detailed notes and design patterns for Design URL Shortener | System Design Interview | AlgoMaster.io.');
