INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-location-based-services-design-uber', 'system-design', 'HLD Interviews - Location Based Services', 'Design Uber', 'Advanced', 15, 'In this chapter, we will explore the high-level design of a ride-hailing platform like Uber.');
