INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-search-aggregation-systems-design-a-web-crawler', 'system-design', 'HLD Interviews - Search Aggregation Systems', 'Design a Web Crawler', 'Advanced', 15, 'Web crawlers serve many purposes beyond search engines. They power price comparison sites, archive the web for historical preservation, gather data for machine learning datasets, monitor brand mentions, and detect copyright violations.');
