INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-e-commerce-marketplace-design-shopify', 'system-design', 'HLD Interviews - E commerce Marketplace', 'Design Shopify', 'Advanced', 15, 'This system design problem covers multi-tenancy, inventory management, payment processing, and handling traffic spikes during flash sales. It tests your ability to design a system that balances consistency (inventory, payments) with high availabil...');
