INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-payment-financial-systems-design-payment-system', 'system-design', 'HLD Interviews - Payment Financial Systems', 'Design Payment System', 'Advanced', 15, 'This problem tests your understanding of distributed systems, consistency guarantees, failure handling, and real-world business constraints. Payment systems have zero tolerance for errors, making them an excellent test of a candidate''s ability to ...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-payment-financial-systems-design-digital-wallet-service', 'system-design', 'HLD Interviews - Payment Financial Systems', 'Design Digital Wallet Service', 'Advanced', 15, 'What makes digital wallets fascinating from an engineering perspective is the zero tolerance for errors. In most systems, a bug might cause a bad user experience or data inconsistency that can be fixed later. In a wallet system, a bug could mean m...');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-payment-financial-systems-design-stock-exchange', 'system-design', 'HLD Interviews - Payment Financial Systems', 'Design Stock Exchange', 'Advanced', 15, 'What makes stock exchange design fascinating from a systems perspective is the extreme demands it places on every component.');
INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-distributed-infrastructure-design-load-balancer', 'system-design', 'HLD Interviews - Distributed Infrastructure', 'Design Load Balancer', 'Advanced', 15, 'Load balancers appear in almost every distributed system architecture. Understanding how to design one from scratch demonstrates deep knowledge of networking, high availability, and system scalability.');
