INSERT INTO topics (id, track_id, category, title, difficulty, estimated_minutes, summary) VALUES ('hld-interviews-distributed-infrastructure-design-a-distributed-key-value-store', 'system-design', 'HLD Interviews - Distributed Infrastructure', 'Design a Distributed Key-Value Store', 'Advanced', 15, 'This problem is a common choice in system design interviews because it tests your understanding of distributed systems fundamentals: partitioning, replication, consistency, and failure handling.');
